//! Signing tests.
//!
//! The C signer is deterministic for a given key, message and seed, and the
//! Rust port performs exactly the same floating-point operations, so the two
//! must produce byte-identical signatures. `tests/sign_vectors.txt` was
//! generated by the C code (see tools/gen_sign_vectors.c).

fn unhex(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
}

struct V {
    logn: u32,
    weak: bool,
    id: Vec<u8>,
    ctx: Vec<u8>,
    hv: Vec<u8>,
    seed: Vec<u8>,
    sk: Vec<u8>,
    vk: Vec<u8>,
    sig: Vec<u8>,
}

fn vectors() -> Vec<V> {
    include_str!("sign_vectors.txt")
        .lines()
        .map(|l| {
            let f: Vec<&str> = l.split(' ').collect();
            assert_eq!(f.len(), 9);
            V {
                logn: f[0].parse().unwrap(),
                weak: f[1] == "1",
                id: unhex(f[2]),
                ctx: unhex(f[3]),
                hv: unhex(f[4]),
                seed: unhex(f[5]),
                sk: unhex(f[6]),
                vk: unhex(f[7]),
                sig: unhex(f[8]),
            }
        })
        .collect()
}

fn sign_seeded(v: &V) -> Option<Vec<u8>> {
    let mut sig = vec![0u8; fndsa::signature_size(v.logn)];
    let r = if v.weak {
        fndsa::sign_weak_seeded(&v.sk, &v.ctx, &v.id, &v.hv, &v.seed, &mut sig)
    } else {
        fndsa::sign_seeded(&v.sk, &v.ctx, &v.id, &v.hv, &v.seed, &mut sig)
    }?;
    sig.truncate(r);
    Some(sig)
}

#[test]
fn byte_identical_to_c() {
    let vs = vectors();
    assert!(vs.len() > 100);
    for (i, v) in vs.iter().enumerate() {
        let sig = sign_seeded(v).unwrap_or_else(|| panic!("vector {i} (logn={}): sign failed", v.logn));
        assert_eq!(sig, v.sig, "vector {i} (logn={}) differs from the C signature", v.logn);
    }
}

#[test]
fn rust_signatures_verify() {
    for v in vectors() {
        let sig = sign_seeded(&v).unwrap();
        let ok = if v.weak {
            fndsa::verify_weak(&sig, &v.vk, &v.ctx, &v.id, &v.hv)
        } else {
            fndsa::verify(&sig, &v.vk, &v.ctx, &v.id, &v.hv)
        };
        assert!(ok, "logn={}", v.logn);
    }
}

#[test]
fn unseeded_signing_works_and_varies() {
    let v = vectors().into_iter().find(|v| v.logn == 9).unwrap();
    let mut s1 = vec![0u8; fndsa::signature_size(9)];
    let mut s2 = vec![0u8; fndsa::signature_size(9)];
    assert_eq!(fndsa::sign(&v.sk, &v.ctx, &v.id, &v.hv, &mut s1), Some(s1.len()));
    assert_eq!(fndsa::sign(&v.sk, &v.ctx, &v.id, &v.hv, &mut s2), Some(s2.len()));
    assert_ne!(s1, s2, "two unseeded signatures must differ");
    assert!(fndsa::verify(&s1, &v.vk, &v.ctx, &v.id, &v.hv));
    assert!(fndsa::verify(&s2, &v.vk, &v.ctx, &v.id, &v.hv));
}

#[test]
fn rejects_bad_inputs() {
    let v = vectors().into_iter().find(|v| v.logn == 9).unwrap();
    let mut sig = vec![0u8; fndsa::signature_size(9)];
    // Wrong entry point for the degree.
    assert!(fndsa::sign_weak_seeded(&v.sk, &v.ctx, &v.id, &v.hv, &v.seed, &mut sig).is_none());
    // Truncated / corrupted key header.
    assert!(fndsa::sign_seeded(&v.sk[..v.sk.len() - 1], &v.ctx, &v.id, &v.hv, &v.seed, &mut sig).is_none());
    let mut bad = v.sk.clone();
    bad[0] = 0x20 | 9;
    assert!(fndsa::sign_seeded(&bad, &v.ctx, &v.id, &v.hv, &v.seed, &mut sig).is_none());
    // Output buffer too small.
    let mut small = vec![0u8; fndsa::signature_size(9) - 1];
    assert!(fndsa::sign_seeded(&v.sk, &v.ctx, &v.id, &v.hv, &v.seed, &mut small).is_none());
    // Oversized context, external mu with the wrong length.
    assert!(fndsa::sign_seeded(&v.sk, &[0u8; 256], &v.id, &v.hv, &v.seed, &mut sig).is_none());
    assert!(fndsa::sign_seeded(&v.sk, &[], fndsa::HASH_ID_EXTMU, &[0u8; 63], &v.seed, &mut sig).is_none());
}
